namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language arts." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilizations." },
            new() { Id = 6, Code = "BIOL", Name = "Biology", Description = "Study of living organisms and life processes." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has contributed to open-source projects used by millions of developers worldwide.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS310", Title = "Database Systems", Description = "Introduction to database design, SQL, normalization, transaction management, and modern NoSQL approaches.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez worked as a database architect at major tech companies before joining academia. She brings real-world experience to her teaching.", IsFeatured = false, DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications in science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an award-winning educator known for making calculus accessible to all students. He has authored three widely-used textbooks.", IsFeatured = true, DepartmentName = "Mathematics" },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH240", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma's research focuses on applied linear algebra and its connections to machine learning and data science.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 3, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a former NASA researcher who brings astrophysics perspectives to introductory physics courses.", IsFeatured = true, DepartmentName = "Physics" },
            new() { Id = 7, DepartmentId = 3, CourseCode = "PHYS220", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research in superconductivity has been recognized internationally. She is passionate about mentoring undergraduate students.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 8, DepartmentId = 4, CourseCode = "ENG110", Title = "College Writing", Description = "Develop effective academic writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", InstructorName = "Prof. David Liu", InstructorBio = "Prof. Liu is a published novelist and essayist who has taught writing at the university level for over 20 years.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 9, DepartmentId = 4, CourseCode = "ENG250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period through the 21st century.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Angela Brooks", InstructorBio = "Dr. Brooks is a leading scholar in African American literature and has curated several literary exhibitions at national museums.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 10, DepartmentId = 5, CourseCode = "HIST101", Title = "World History to 1500", Description = "Exploration of major civilizations, cultural exchanges, and turning points in human history before the modern era.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant has conducted archaeological fieldwork across three continents and authored several books on ancient civilizations.", IsFeatured = false, DepartmentName = "History" },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST205", Title = "Modern European History", Description = "Political, social, and cultural developments in Europe from the Enlightenment to the present day.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Olivia Muller", InstructorBio = "Dr. Muller specializes in 20th-century European history and has been a visiting scholar at universities in Berlin and Paris.", IsFeatured = false, DepartmentName = "History" },
            new() { Id = 12, DepartmentId = 6, CourseCode = "BIOL101", Title = "Introduction to Biology", Description = "Foundational concepts in cell biology, genetics, evolution, and ecology with weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed 10:00–10:50 AM + Lab Fri 1:00–3:50 PM", InstructorName = "Dr. Karen Okafor", InstructorBio = "Dr. Okafor is a molecular biologist whose research on gene expression has been published in leading scientific journals.", IsFeatured = true, DepartmentName = "Biology" },
            new() { Id = 13, DepartmentId = 6, CourseCode = "BIOL310", Title = "Genetics", Description = "Principles of heredity, molecular genetics, gene regulation, and genomic technologies.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres leads a research lab focused on CRISPR technology and its therapeutic applications. He mentors students in cutting-edge genetic research.", IsFeatured = false, DepartmentName = "Biology" }
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database.
        return true;
    }
}

