@page "/"

@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p class="lead">Explore our departments and courses for the upcoming semester.</p>
    </div>

    <section class="featured-section">
        <h2>Featured Courses</h2>
        <div class="course-grid">
            @foreach (var course in featuredCourses)
            {
                <div class="course-card featured">
                    <span class="badge">@course.CourseCode</span>
                    <h3>@course.Title</h3>
                    <p>@course.DepartmentName &middot; @course.Credits credits</p>
                    <p class="description">@course.Description</p>
                    <a href="/courses/@course.Id" class="btn">View Details</a>
                </div>
            }
        </div>
    </section>

    <section class="departments-section">
        <h2>Departments</h2>
        <div class="department-grid">
            @foreach (var dept in departments)
            {
                <div class="department-card">
                    <h3>@dept.Name</h3>
                    <p>@dept.Description</p>
                    <a href="/courses?departmentId=@dept.Id" class="btn btn-outline">Browse Courses</a>
                </div>
            }
        </div>
    </section>
</div>

@code {
    private List<UniversityCourseCatalog.Models.Course> featuredCourses = new();
    private List<UniversityCourseCatalog.Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetAllDepartments();
    }
}

