@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="search-filters">
    <form method="get" action="/courses">
        <div class="filter-row">
            <input type="text" name="search" value="@searchTerm" placeholder="Search courses..." class="search-input" />
            <select name="departmentId" class="filter-select">
                <option value="">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id" selected="@(selectedDepartmentId == dept.Id)">@dept.Name</option>
                }
            </select>
            <button type="submit" class="btn">Search</button>
        </div>
    </form>
</div>

<div class="results-count">
    <p>Showing @courses.Count course(s)</p>
</div>

<div class="course-list">
    @if (courses.Count == 0)
    {
        <p class="no-results">No courses found matching your criteria.</p>
    }
    else
    {
        @foreach (var course in courses)
        {
            <div class="course-card">
                <div class="course-header">
                    <span class="badge">@course.CourseCode</span>
                    <span class="credits">@course.Credits credits</span>
                </div>
                <h3>@course.Title</h3>
                <p class="meta">@course.DepartmentName &middot; @course.InstructorName</p>
                <p class="schedule">@course.Schedule</p>
                <a href="/courses/@course.Id" class="btn btn-outline">View Details</a>
            </div>
        }
    }
</div>

@code {
    [SupplyParameterFromQuery] public string? search { get; set; }
    [SupplyParameterFromQuery] public int? departmentId { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();
    private string? searchTerm;
    private int? selectedDepartmentId;

    protected override void OnInitialized()
    {
        searchTerm = search;
        selectedDepartmentId = departmentId;
        departments = CatalogService.GetAllDepartments();
        courses = CatalogService.SearchCourses(searchTerm, selectedDepartmentId);
    }
}

