@if (submitted)
{
    <div class="success-message">
        <h2>Request Submitted Successfully</h2>
        <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for
            <strong>@selectedCourseName</strong> has been received.</p>
        <p>The registrar's office will contact you with confirmation details.</p>
        <a href="/courses" class="btn">Browse More Courses</a>
    </div>
}
else
{
    <div class="enrollment-form-container">
        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm">
            <DataAnnotationsValidator />
            <ValidationSummary />

            <div class="form-group">
                <label for="studentName">Full Name</label>
                <InputText id="studentName" @bind-Value="model.StudentName" class="form-control" />
                <ValidationMessage For="() => model.StudentName" />
            </div>

            <div class="form-group">
                <label for="studentId">Student ID</label>
                <InputText id="studentId" @bind-Value="model.StudentId" class="form-control" />
                <ValidationMessage For="() => model.StudentId" />
            </div>

            <div class="form-group">
                <label for="courseId">Course</label>
                <InputSelect id="courseId" @bind-Value="model.CourseId" class="form-control">
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.CourseCode - @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.CourseId" />
            </div>

            <button type="submit" class="btn">Submit Enrollment Request</button>
        </EditForm>
    </div>
}

@code {
    [SupplyParameterFromQuery] public int? courseId { get; set; }
    [SupplyParameterFromForm] private EnrollmentRequest model { get; set; } = new();

    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetAllCourses();
        if (courseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = courseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourseById(model.CourseId);
        selectedCourseName = course != null ? $"{course.CourseCode} - {course.Title}" : "Unknown";
        CatalogService.SubmitEnrollmentRequest(model);
        submitted = true;
    }
}
